arguments.command:
cd /workspace/submission && python3 -c "
import os
total=0; count=0
for base,dirs,files in os.walk('.'):
    for name in dirs+files:
        p=os.path.join(base,name); count+=1
        if os.path.isfile(p): total+=os.path.getsize(p)
        print(('d' if os.path.isdir(p) else 'f'), p, os.path.getsize(p) if os.path.isfile(p) else '')
print('entries', count, 'bytes', total)
"
